// The browse-scale home-continue duty (D5/D7): ONE server-composed
// round-trip — scored order with the recency tiebreak, the ≤50 bound cut
// AFTER the score order, the ContinueRow composition through namerFor (the
// viewer's ChainMutes included), the tuple-parity next pick, the honest
// duration floor, query-time artwork, and the invisible-library posture —
// all over the real router wiring and a real store.

// newHomeAPI is the home fixture: the newRecsAPI shape plus the title walk
// (TitleSources — the leg the ChainMutes floor shows through names) and the
// Art service (the query-time artwork leg composes instead of degrading).
func newHomeAPI(t *testing.T) (http.Handler, *store.Store, int64) {
	t.Helper()
	st := openAPIStore(t)
	libID, err := st.CreateLibrary(context.Background(), "serial", "/media/home", "Recs")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	// The see-all admin scope (ledger slot 0 — the slot the fixture's
	// access.System() writes stamp).
	h := homeRouter(t, st, access.Admin())
	return h, st, libID
}

// homeRouter builds the REAL mountV1Routes wiring behind a synthetic client
// principal carrying the given viewer (the handlers_viewer_test seam — the
// carrier viewerFor memoizes, so the scope flows through every handler).
func homeRouter(t *testing.T, st *store.Store, v access.Viewer) http.Handler {
	t.Helper()
	h := &app{deps: Deps{
		AdminToken: adminToken,
		Store:      st,
		Art:        art.NewService(st, t.TempDir()),
		ModulePresentation: func(_ context.Context, _ string, _ int64) (ModulePresentation, error) {
			return ModulePresentation{
				SourceChain:  []titleSourceBinding{{ID: recsMetaNS, Enabled: true}},
				TitleSources: []titleSourceBinding{{ID: recsMetaNS, Enabled: true}},
			}, nil
		},
	}}
	r := chi.NewRouter()
	r.Use(principalInjector(RoleClient))
	r.Use(principalViewerInjector(v))
	r.Route("/api/v1", func(r chi.Router) { mountV1Routes(r, h) })
	return r
}

// homeSeriesDoc is a series document with the namespace's synopsis group,
// optionally the config title-walk title and a namespace poster (the
// artwork leg's input).
func homeSeriesDoc(dir, title, poster string) map[string]any {
	ns := map[string]any{"description": "d", "genres": []string{"drama"}}
	if title != "" {
		ns["title"] = title
	}
	if poster != "" {
		ns["poster"] = poster
	}
	return map[string]any{
		"parsed":  map[string]any{"backing": "directory", "dir_name_raw": dir},
		"sources": map[string]any{recsMetaNS: ns},
	}
}

// homeEpisodeDoc is an episode document anchored to its series with the
// parsed (season, episode) pair; viewTitle is the _view floor, ffprobe the
// verbatim duration blob (nil = the honest-absence case), title the
// episode's own convention title (the metadata projection's episode group).
func homeEpisodeDoc(seriesPath string, season, episode int64, viewTitle string, ffprobe map[string]any, title string) map[string]any {
	ns := map[string]any{"season": season, "episode": episode}
	if title != "" {
		ns["title"] = title
	}
	doc := map[string]any{
		"parsed":  map[string]any{"series_relative_path": seriesPath},
		"sources": map[string]any{recsMetaNS: ns},
	}
	if viewTitle != "" {
		doc["_view"] = map[string]any{"title": map[string]any{"value": viewTitle}}
	}
	if ffprobe != nil {
		doc["ffprobe"] = ffprobe
	}
	return doc
}

// decodeHome decodes the home wire shape.
func decodeHome(t *testing.T, resp *http.Response) homeResponse {
	t.Helper()
	var hr homeResponse
	if err := json.NewDecoder(resp.Body).Decode(&hr); err != nil {
		t.Fatalf("decode homeResponse: %v", err)
	}
	return hr
}

// putProgress writes one legacy-slot position with a strictly later stamp
// than the previous call's (the recency tiebreak needs distinct stamps).
func putProgress(t *testing.T, st *store.Store, itemID string, pos int64) {
	t.Helper()
	if _, err := st.PutProgress(context.Background(), itemID, pos, access.System()); err != nil {
		t.Fatalf("PutProgress %s: %v", itemID, err)
	}
	time.Sleep(2 * time.Millisecond)
}

// rowWireCurrent re-marshals one row's current block and reports whether
// duration_seconds is on the wire (the omitempty observability probe).
func rowHasDuration(t *testing.T, row continueRow) bool {
	t.Helper()
	b, err := json.Marshal(row)
	if err != nil {
		t.Fatalf("marshal row: %v", err)
	}
	var wire struct {
		Current map[string]any `json:"current"`
	}
	if err := json.Unmarshal(b, &wire); err != nil {
		t.Fatalf("unmarshal row: %v", err)
	}
	_, has := wire.Current["duration_seconds"]
	return has
}

// wantNext asserts one row's next offer (item id + label) or its absence.
func wantNext(t *testing.T, row continueRow, wantID, wantLabel string) {
	t.Helper()
	if wantID == "" {
		if row.Next != nil {
			t.Fatalf("next = %+v, want absent", row.Next)
		}
		return
	}
	if row.Next == nil {
		t.Fatalf("next absent, want %s (%s)", wantID, wantLabel)
	}
	if row.Next.ItemID != wantID || row.Next.Label != wantLabel {
		t.Fatalf("next = %s (%s), want %s (%s)", row.Next.ItemID, row.Next.Label, wantID, wantLabel)
	}
}

func TestHomeRoute(t *testing.T) {
	t.Run("scored_order_recency_tiebreak_and_bound", func(t *testing.T) {
		h, st, lib := newHomeAPI(t)

		// The weighted film scores above the plain ones; 55 rows total so
		// the ≤50 bound bites AFTER the score order (the oldest plain rows
		// drop, the high scorer never does).
		tagged := seedRecsItem(t, st, lib, "itm_h_tag", "tagged.mkv", map[string]any{
			"sources": map[string]any{recsMetaNS: map[string]any{"description": "d", "genres": []string{"action"}}},
		}, time.Time{})
		for i := 0; i < 54; i++ {
			seedRecsItem(t, st, lib, fmt.Sprintf("itm_h_%02d", i), fmt.Sprintf("f%02d.mkv", i), map[string]any{}, time.Time{})
		}
		if err := st.ApplyTagWeights(context.Background(), []string{"action"}, time.Now().UTC()); err != nil {
			t.Fatalf("ApplyTagWeights: %v", err)
		}
		for i := 0; i < 54; i++ {
			putProgress(t, st, fmt.Sprintf("itm_h_%02d", i), 100)
		}
		putProgress(t, st, tagged.ID, 100)

		resp := doRequest(t, h, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		hr := decodeHome(t, resp)
		if len(hr.Continue) != 50 {
			t.Fatalf("rows = %d, want 50 (the server-side bound)", len(hr.Continue))
		}
		// The scored default: the weighted film first despite the OLDEST
		// recency slot it would hold under a pure recency rail; then the 49
		// NEWEST plain rows, newest first (the recency tiebreak at the same
		// score tier).
		if got := hr.Continue[0].Current.ItemID; got != tagged.ID {
			t.Fatalf("first row = %s, want the scored %s", got, tagged.ID)
		}
		for i, row := range hr.Continue[1:] {
			want := fmt.Sprintf("itm_h_%02d", 53-i)
			if row.Current.ItemID != want {
				t.Fatalf("row %d = %s, want the recency tiebreak order %s", i+1, row.Current.ItemID, want)
			}
			if row.Current.PositionSeconds != 100 {
				t.Fatalf("row %d position = %d, want 100", i+1, row.Current.PositionSeconds)
			}
		}
	})

	t.Run("serial_row_composition_honest_duration", func(t *testing.T) {
		h, st, lib := newHomeAPI(t)
		sr := seedRecsSeries(t, st, lib, "show", homeSeriesDoc("Show", "", "https://img.example/show.jpg"))
		ep := seedRecsItem(t, st, lib, "itm_h_e1", "show/e1.mkv", homeEpisodeDoc("show", 2, 3, "Episode Three",
			map[string]any{"format": map[string]any{"duration": "1234.6"}}, "The Decision"), time.Time{})
		// The unstarted next episode: in the series' episode list (the pick's
		// candidate set) but carrying no progress row (never in the rail).
		epNext := seedRecsItem(t, st, lib, "itm_h_e2", "show/e2.mkv", homeEpisodeDoc("show", 2, 4, "Episode Four", nil, ""), time.Time{})
		// A fact-less film row: the honest bar-less case beside the serial
		// one (written last — newer recency, lower score tier).
		film := seedRecsItem(t, st, lib, "itm_h_film", "film.mkv", map[string]any{}, time.Time{})
		putProgress(t, st, film.ID, 300)
		putProgress(t, st, ep.ID, 500)

		resp := doRequest(t, h, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		hr := decodeHome(t, resp)
		if len(hr.Continue) != 2 {
			t.Fatalf("rows = %d, want 2", len(hr.Continue))
		}
		// The episode scores above the plain film (the joined drama weight)
		// and serves first.
		row := hr.Continue[0]
		if row.Current.ItemID != ep.ID {
			t.Fatalf("first row = %s, want %s", row.Current.ItemID, ep.ID)
		}
		if row.SeriesID != sr.ID {
			t.Fatalf("series_id = %q, want %q", row.SeriesID, sr.ID)
		}
		if row.SeriesDisplay != "Show" {
			t.Fatalf("series_display_name = %q, want the dir_name_raw floor %q", row.SeriesDisplay, "Show")
		}
		if row.LibraryID != lib || row.LibraryName != "Recs" {
			t.Fatalf("library = (%d,%q), want (%d,%q)", row.LibraryID, row.LibraryName, lib, "Recs")
		}
		// Query-time artwork: the owning series' namespace poster, served
		// raw while unstaged.
		if row.Artwork != "https://img.example/show.jpg" {
			t.Fatalf("artwork = %q, want the composed series poster", row.Artwork)
		}
		// The composed episode facts: display rides the config title walk
		// (the source title beats the _view floor), the raw pair serves,
		// the episode's own convention title rides the metadata projection,
		// the ffprobe duration rounds to whole seconds.
		if row.Current.Display != "The Decision" {
			t.Fatalf("display = %q, want the title-walk name", row.Current.Display)
		}
		if row.Current.Season == nil || *row.Current.Season != 2 || row.Current.Episode == nil || *row.Current.Episode != 3 {
			t.Fatalf("season/episode = %v/%v, want 2/3", row.Current.Season, row.Current.Episode)
		}
		if row.Current.EpisodeTitle != "The Decision" {
			t.Fatalf("episode_title = %q, want the convention projection's title", row.Current.EpisodeTitle)
		}
		if row.Current.DurationSeconds == nil || *row.Current.DurationSeconds != 1235 {
			t.Fatalf("duration_seconds = %v, want 1235 (1234.6 rounded)", row.Current.DurationSeconds)
		}
		// The pick: the lowest (season, episode) strictly after the highest
		// STARTED one — S02E04, the unstarted episode.
		wantNext(t, row, epNext.ID, "S02E04")
		// The honest absence: no ffprobe fact — the field is OMITTED, not
		// zero, never guessed.
		barLess := hr.Continue[1]
		if barLess.Current.ItemID != film.ID {
			t.Fatalf("second row = %s, want %s", barLess.Current.ItemID, film.ID)
		}
		if rowHasDuration(t, barLess) {
			t.Fatal("duration_seconds on the wire for a fact-less item — the honest omission broke")
		}
		// The film row carries no series fields and no next.
		if barLess.SeriesID != "" || barLess.SeriesDisplay != "" {
			t.Fatalf("film series fields = (%q,%q), want the honest empty floors", barLess.SeriesID, barLess.SeriesDisplay)
		}
		wantNext(t, barLess, "", "")
	})

	t.Run("next_pick_tuple_parity", func(t *testing.T) {
		// The watch page's client derivation vectors (nextup.ts
		// nextEpisodeAfter / nextup.test.ts), re-pinned over the server
		// pick — tuple parity is the contract.
		showItem := func(id string, s, e int64) store.Item {
			return store.Item{ID: id, Document: recsDoc(t, homeEpisodeDoc("show", s, e, "", nil, ""))}
		}
		filmItem := store.Item{ID: "itm_film", Document: recsDoc(t, map[string]any{})}
		cases := []struct {
			name       string
			startS, st int64
			eps        []store.Item
			wantID     string
			wantLabel  string
		}{
			{
				name: "adjacent pick — watching S01E02, the list's S01E03 is next",
				st:   2, startS: 1,
				eps:    []store.Item{showItem("a", 1, 1), showItem("b", 1, 2), showItem("c", 1, 3)},
				wantID: "c", wantLabel: "S01E03",
			},
			{
				name: "skip-across ordering — the lowest strictly-after wins, not the first seen",
				st:   4, startS: 1,
				eps:    []store.Item{showItem("a", 1, 2), showItem("b", 2, 3), showItem("c", 2, 1), showItem("d", 3, 9)},
				wantID: "c", wantLabel: "S02E01",
			},
			{
				name: "equal facts are not strictly after — the started episode never wins",
				st:   2, startS: 1,
				eps:    []store.Item{showItem("a", 1, 1), showItem("b", 1, 2)},
				wantID: "", wantLabel: "",
			},
			{
				name: "last episode — nothing strictly after, no rewatch",
				st:   1, startS: 2,
				eps:    []store.Item{showItem("a", 1, 3), showItem("b", 2, 1)},
				wantID: "", wantLabel: "",
			},
			{
				name: "facts-less candidates are skipped, never fatal",
				st:   1, startS: 1,
				eps:    []store.Item{filmItem, showItem("b", 1, 2)},
				wantID: "b", wantLabel: "S01E02",
			},
		}
		for _, tc := range cases {
			t.Run(tc.name, func(t *testing.T) {
				id, label, ok := homeNextPick(tc.eps, tc.startS, tc.st)
				if tc.wantID == "" {
					if ok {
						t.Fatalf("pick = %s (%s), want none", id, label)
					}
					return
				}
				if !ok || id != tc.wantID || label != tc.wantLabel {
					t.Fatalf("pick = %s (%s, %v), want %s (%s)", id, label, ok, tc.wantID, tc.wantLabel)
				}
			})
		}
	})

	t.Run("films_carry_no_next_and_no_series", func(t *testing.T) {
		h, st, lib := newHomeAPI(t)
		seedRecsSeries(t, st, lib, "done", homeSeriesDoc("Done", "", ""))
		fin := seedRecsItem(t, st, lib, "itm_h_fin", "done/fin.mkv", homeEpisodeDoc("done", 1, 9, "", nil, ""), time.Time{})
		film := seedRecsItem(t, st, lib, "itm_h_film", "film.mkv", map[string]any{}, time.Time{})
		putProgress(t, st, film.ID, 300)
		putProgress(t, st, fin.ID, 200)

		resp := doRequest(t, h, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		hr := decodeHome(t, resp)
		if len(hr.Continue) != 2 {
			t.Fatalf("rows = %d, want 2", len(hr.Continue))
		}
		// The episode scores above the plain film (the joined drama weight),
		// so it serves first; the film row: the series fields floor honestly
		// empty, no next — it surfaces as a continue row without a next
		// offer.
		doneRow := hr.Continue[0]
		if doneRow.Current.ItemID != fin.ID || doneRow.SeriesID == "" {
			t.Fatalf("first row = %s (series %q), want the series' last episode", doneRow.Current.ItemID, doneRow.SeriesID)
		}
		wantNext(t, doneRow, "", "")
		filmRow := hr.Continue[1]
		if filmRow.Current.ItemID != film.ID {
			t.Fatalf("second row = %s, want the film", filmRow.Current.ItemID)
		}
		if filmRow.SeriesID != "" || filmRow.SeriesDisplay != "" {
			t.Fatalf("film series fields = (%q,%q), want the honest empty floors", filmRow.SeriesID, filmRow.SeriesDisplay)
		}
		wantNext(t, filmRow, "", "")
	})

	t.Run("chain_mutes_floor_names_and_artwork", func(t *testing.T) {
		_, st, lib := newHomeAPI(t)
		seedRecsSeries(t, st, lib, "show", homeSeriesDoc("Show", "Enriched Show", "https://img.example/show.jpg"))
		ep := seedRecsItem(t, st, lib, "itm_h_m1", "show/e1.mkv", homeEpisodeDoc("show", 1, 1, "", nil, ""), time.Time{})
		// The ledger slot is the VIEWER's (l6-accounts D7): the user-7
		// viewers below read their own slot, so the row is written as
		// user 7.
		if _, err := st.PutProgress(context.Background(), ep.ID, 100, access.User(7, []int64{lib}, nil)); err != nil {
			t.Fatalf("PutProgress: %v", err)
		}

		// The unmuted viewer: the title walk resolves the source title and
		// the poster composes.
		granted := homeRouter(t, st, access.User(7, []int64{lib}, nil))
		resp := doRequest(t, granted, http.MethodGet, "/api/v1/home", "", adminToken)
		hr := decodeHome(t, resp)
		defer resp.Body.Close()
		if len(hr.Continue) != 1 || hr.Continue[0].SeriesDisplay != "Enriched Show" || hr.Continue[0].Artwork != "https://img.example/show.jpg" {
			t.Fatalf("unmuted row = (%q, %q), want the walked name and the poster",
				hr.Continue[0].SeriesDisplay, hr.Continue[0].Artwork)
		}
		// The muted viewer (ChainMutes floor the walk — 10.4): the same
		// rows, per-response only — the name floors past the muted source
		// to the dir_name_raw floor and the poster composes nothing.
		muted := homeRouter(t, st, access.User(7, []int64{lib}, map[string]bool{recsMetaNS: true}))
		resp2 := doRequest(t, muted, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp2.Body.Close()
		hr2 := decodeHome(t, resp2)
		if len(hr2.Continue) != 1 {
			t.Fatalf("rows = %d, want 1", len(hr2.Continue))
		}
		row := hr2.Continue[0]
		if row.SeriesDisplay != "Show" {
			t.Fatalf("muted series_display_name = %q, want the dir_name_raw floor past the muted source", row.SeriesDisplay)
		}
		if row.Artwork != "" {
			t.Fatalf("muted artwork = %q, want the honest absence", row.Artwork)
		}
	})

	t.Run("invisible_library_never_leaks", func(t *testing.T) {
		st := openAPIStore(t)
		ctx := context.Background()
		libA, err := st.CreateLibrary(ctx, "serial", "/media/a", "A")
		if err != nil {
			t.Fatalf("CreateLibrary A: %v", err)
		}
		libB, err := st.CreateLibrary(ctx, "serial", "/media/b", "B")
		if err != nil {
			t.Fatalf("CreateLibrary B: %v", err)
		}
		writer := access.User(42, []int64{libA, libB}, nil)
		for _, tc := range []struct {
			lib  int64
			path string
			id   string
		}{
			{libA, "sa", "itm_h_sa"},
			{libB, "sb", "itm_h_sb"},
		} {
			seedRecsSeries(t, st, tc.lib, tc.path, homeSeriesDoc(tc.path, "", ""))
			seedRecsItem(t, st, tc.lib, tc.id, tc.path+"/e1.mkv", homeEpisodeDoc(tc.path, 1, 1, "", nil, ""), time.Time{})
			if _, err := st.PutProgress(ctx, tc.id, 100, writer); err != nil {
				t.Fatalf("PutProgress %s: %v", tc.id, err)
			}
		}
		// The denied viewer's grant set excludes libB: the rail carries no
		// row from it — no ids, no names, no counts.
		denied := homeRouter(t, st, access.User(42, []int64{libA}, nil))
		resp := doRequest(t, denied, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want 200", resp.StatusCode)
		}
		hr := decodeHome(t, resp)
		if len(hr.Continue) != 1 {
			t.Fatalf("denied rows = %d, want exactly the granted library's 1", len(hr.Continue))
		}
		if hr.Continue[0].LibraryID != libA || hr.Continue[0].Current.ItemID != "itm_h_sa" {
			t.Fatalf("denied row = (%d,%s), want only libA's row", hr.Continue[0].LibraryID, hr.Continue[0].Current.ItemID)
		}
		// The granted viewer holds both grants: both rows serve.
		granted := homeRouter(t, st, access.User(42, []int64{libA, libB}, nil))
		resp2 := doRequest(t, granted, http.MethodGet, "/api/v1/home", "", adminToken)
		defer resp2.Body.Close()
		hr2 := decodeHome(t, resp2)
		if len(hr2.Continue) != 2 {
			t.Fatalf("granted rows = %d, want 2", len(hr2.Continue))
		}
		got := map[int64]string{}
		for _, row := range hr2.Continue {
			got[row.LibraryID] = row.Current.ItemID
		}
		if got[libA] != "itm_h_sa" || got[libB] != "itm_h_sb" {
			t.Fatalf("granted rows = %v, want both libraries' rows", got)
		}
	})
}
